script.setup:
// spectral.js mixes the three paints like real pigments (Kubelka–Munk) into a lookup table;
// a GPU simulation swirls the paint amounts and the display shader reads the mixed color.
const mod = await ctx.utils.import("https://esm.sh/spectral.js@3.0.0");
const spectral = mod.default ?? mod;
const gl = ctx.gl;
gl.getExtension("EXT_color_buffer_float");
const N = 33, LAYERS = 9;
const lut = gl.createTexture();
gl.bindTexture(gl.TEXTURE_3D, lut);
gl.texImage3D(gl.TEXTURE_3D, 0, gl.RGBA8, N, N, LAYERS, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
for (const p of [gl.TEXTURE_MIN_FILTER, gl.TEXTURE_MAG_FILTER]) gl.texParameteri(gl.TEXTURE_3D, p, gl.LINEAR);
for (const p of [gl.TEXTURE_WRAP_S, gl.TEXTURE_WRAP_T, gl.TEXTURE_WRAP_R]) gl.texParameteri(gl.TEXTURE_3D, p, gl.CLAMP_TO_EDGE);
// The table: x = share of paint A, y = share of B (C gets the rest), z = how much paint covers the paper.
const buildLut = (a, b, c, paper) => {
  const C = (rgb) => new spectral.Color(rgb.map((v) => v * 255));
  const A = C(a), B = C(b), Cc = C(c), Paper = C(paper);
  const data = new Uint8Array(N * N * LAYERS * 4);
  for (let k = 0; k < LAYERS; k++) for (let j = 0; j < N; j++) for (let i = 0; i < N; i++) {
    let wa = i / (N - 1), wb = j / (N - 1);
    if (wa + wb > 1) { const t = wa + wb; wa /= t; wb /= t; }
    const cover = k / (LAYERS - 1);
    const rgb = spectral.mix([A, wa * cover], [B, wb * cover], [Cc, (1 - wa - wb) * cover], [Paper, 1 - cover]).sRGB;
    // Mixes can land slightly outside sRGB (e.g. 259); clamp so bytes don't wrap around.
    data.set([...rgb.map((v) => Math.min(255, Math.max(0, Math.round(v)))), 255], ((k * N + j) * N + i) * 4);
  }
  gl.bindTexture(gl.TEXTURE_3D, lut);
  gl.texSubImage3D(gl.TEXTURE_3D, 0, 0, 0, 0, N, N, LAYERS, gl.RGBA, gl.UNSIGNED_BYTE, data);
};
const sim = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_prev; uniform vec2 u_resolution; uniform float u_time; uniform float u_dt;
uniform float u_flow; uniform float u_init; uniform vec4 u_pen; uniform vec2 u_penVel; uniform vec4 u_drop;
` + ctx.utils.glsl.SIMPLEX_3D + `
vec2 aspect() { return vec2(u_resolution.x / u_resolution.y, 1.0); }
float blob(vec2 p, vec2 c, float r) { vec2 d = (p - c) * aspect(); return exp(-dot(d, d) / (r * r)); }
float disc(vec2 p, vec2 c, float r) { return smoothstep(r, r * 0.8, length((p - c) * aspect())); }
vec3 onehot(float i) { return vec3(i < 0.5 ? 1.0 : 0.0, abs(i - 1.0) < 0.5 ? 1.0 : 0.0, i > 1.5 ? 1.0 : 0.0); }
void main(){
  vec2 uv = v_uv;
  if (u_init > 0.5) {
    vec3 c = vec3(disc(uv, vec2(0.4, 0.58), 0.22), disc(uv, vec2(0.6, 0.58), 0.22), disc(uv, vec2(0.5, 0.4), 0.21)) * 1.2;
    outColor = vec4(c, 1.0); return;
  }
  // A slow curl-noise swirl moves the paint around; the brush drags it along.
  vec3 q = vec3(uv * aspect() * 2.6, u_time * 0.05);
  float e = 0.01;
  vec2 vel = vec2(snoise(q + vec3(0, e, 0)) - snoise(q - vec3(0, e, 0)), -(snoise(q + vec3(e, 0, 0)) - snoise(q - vec3(e, 0, 0)))) / (2.0 * e);
  vel *= 0.02 * u_flow;
  float brush = u_pen.z > 0.0 ? blob(uv, u_pen.xy, u_pen.z) : 0.0;
  vel += u_penVel * brush;
  vec2 back = uv - vel * u_dt / aspect();
  vec2 px = 1.0 / u_resolution;
  vec3 c = texture(u_prev, back).rgb;
  vec3 around = (texture(u_prev, back + vec2(px.x, 0)).rgb + texture(u_prev, back - vec2(px.x, 0)).rgb + texture(u_prev, back + vec2(0, px.y)).rgb + texture(u_prev, back - vec2(0, px.y)).rgb) * 0.25;
  c = mix(c, around, 0.02);
  if (u_pen.w >= 0.0 && u_pen.w < 2.5) c += onehot(u_pen.w) * brush * u_dt * 6.0;
  if (u_drop.z > 0.0) c += onehot(u_drop.w) * disc(uv, u_drop.xy, u_drop.z) * 1.2;
  c *= 1.0 - 0.012 * u_dt;
  float sum = c.r + c.g + c.b;
  if (sum > 2.5) c *= 2.5 / sum;
  outColor = vec4(max(c, 0.0), 1.0);
}`);
const show = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; precision highp sampler3D; in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_field; uniform sampler3D u_lut; uniform vec2 u_resolution; uniform bool u_compare;
uniform vec3 u_paintA; uniform vec3 u_paintB; uniform vec3 u_paintC; uniform vec3 u_paper;
float hash(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
void main(){
  vec3 c = texture(u_field, v_uv).rgb;
  float sum = c.r + c.g + c.b;
  vec3 wgt = sum > 1e-4 ? c / sum : vec3(0.0, 0.0, 1.0);
  float cover = 1.0 - exp(-sum * 2.2);
  vec3 col;
  bool rgbSide = u_compare && v_uv.x > 0.5;
  if (rgbSide) {
    // Plain RGB averaging, for comparison: blue + yellow goes grey instead of green.
    col = mix(u_paper, wgt.r * u_paintA + wgt.g * u_paintB + wgt.b * u_paintC, cover);
  } else {
    const float N = 33.0, L = 9.0;
    col = texture(u_lut, vec3((wgt.r * (N - 1.0) + 0.5) / N, (wgt.g * (N - 1.0) + 0.5) / N, (cover * (L - 1.0) + 0.5) / L)).rgb;
  }
  // Wet sheen from the paint's thickness, and a little paper grain.
  vec2 px = 1.0 / u_resolution;
  float sx = dot(texture(u_field, v_uv + vec2(px.x * 2.0, 0)).rgb - texture(u_field, v_uv - vec2(px.x * 2.0, 0)).rgb, vec3(1));
  float sy = dot(texture(u_field, v_uv + vec2(0, px.y * 2.0)).rgb - texture(u_field, v_uv - vec2(0, px.y * 2.0)).rgb, vec3(1));
  float light = clamp(0.5 + (sx * -0.6 + sy * 0.8) * 3.0, 0.0, 1.0);
  col *= 0.92 + 0.16 * light * cover;
  col += pow(light, 6.0) * 0.12 * cover;
  col *= 0.97 + 0.03 * hash(floor(v_uv * u_resolution / 2.0));
  if (u_compare && abs(v_uv.x - 0.5) < px.x * 1.5) col = vec3(0.1);
  outColor = vec4(col, 1.0);
}`);
Object.assign(ctx.state, { buildLut, lut, sim, show, field: null, lutKey: "", drop: 0, moved: false });

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, [w, h] = ctx.resolution;
// Rebuild the spectral mixing table when a paint color changes (about 10k mixes).
const key = JSON.stringify([u.u_paintA, u.u_paintB, u.u_paintC, u.u_paper]);
if (key !== s.lutKey) { s.lutKey = key; s.buildLut(u.u_paintA, u.u_paintB, u.u_paintC, u.u_paper); }
const fw = Math.max(1, Math.floor(w / 2)), fh = Math.max(1, Math.floor(h / 2));
let init = 0;
if (!s.field || s.field.width !== fw || s.field.height !== fh) {
  s.field = ctx.utils.createPingPong(fw, fh, { internalFormat: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT, filter: gl.LINEAR });
  init = 1;
}
// Brush: hold the button and drag to lay down (or just smear) paint.
s.moved ||= ctx.mouse[0] !== 0.5 || ctx.mouse[1] !== 0.5;
const dt = Math.min(ctx.dt, 1 / 30);
const painting = s.moved && ctx.mouseDown;
const brush = [ctx.mouse[0], 1 - ctx.mouse[1], painting ? u.u_size : 0, u.u_brush === 3 ? -1 : u.u_brush];
const vel = painting ? [(ctx.mouse[0] - ctx.mousePrev[0]) / Math.max(ctx.dt, 1e-3) * w / h, -(ctx.mouse[1] - ctx.mousePrev[1]) / Math.max(ctx.dt, 1e-3)] : [0, 0];
// Now and then a fresh drop of paint lands somewhere.
let drop = [0, 0, 0, 0];
s.drop -= dt * u.u_drops;
if (s.drop <= 0 && !init) { s.drop = 1; drop = [0.15 + Math.random() * 0.7, 0.15 + Math.random() * 0.7, 0.04 + Math.random() * 0.06, Math.floor(Math.random() * 3)]; }
const read = s.field.read(), write = s.field.write();
gl.bindFramebuffer(gl.FRAMEBUFFER, write.framebuffer);
gl.viewport(0, 0, fw, fh);
gl.useProgram(s.sim);
ctx.utils.bindTexture(s.sim, "u_prev", read.texture, 0);
ctx.utils.drawFullscreen(s.sim, { u_resolution: [fw, fh], u_dt: dt, u_init: init, u_pen: brush, u_penVel: vel, u_drop: drop, u_flow: u.u_flow });
s.field.swap();
gl.bindFramebuffer(gl.FRAMEBUFFER, null);
gl.viewport(0, 0, w, h);
gl.useProgram(s.show);
ctx.utils.bindTexture(s.show, "u_field", s.field.read().texture, 0);
gl.activeTexture(gl.TEXTURE1); gl.bindTexture(gl.TEXTURE_3D, s.lut);
ctx.utils.setUniforms(s.show, { u_lut: 1 });
ctx.utils.drawFullscreen(s.show, { u_lut: 1 });
